var arr=new System.Collections.Generic.List<object>();var g=UnityEngine.GameObject.Find("GameplayTilemap");var tm=g.GetComponent<UnityEngine.Tilemaps.Tilemap>();foreach(var p in tm.cellBounds.allPositionsWithin){var t=tm.GetTile(p);if(t==null)continue;var sp=tm.GetSprite(p);if(sp!=null&&(sp.name.Contains("Sedan")||sp.name.Contains("Wrecked")))arr.Add(new{x=p.x,y=p.y,sprite=sp.name,bounds=sp.bounds.size.ToString()});}return arr;
